// El frontend (componente Cualificacion) envía:
// { cliente, email, telefono, respuestas, score_parcial, timestamp }
// respuestas = { objetivo: [...], historial, recurrencia, presupuesto,
//                plazo, detonante, municipio }
//
// Este email es el SEGUNDO aviso al negocio (el primero, inmediato al
// dejar los datos de contacto, lo manda "Landing IA — Leads"). Solo se
// dispara si el lead completa las 6 preguntas — no incluye el informe,
// igual que el otro.

const body = $input.first().json.body || $input.first().json;
const r = body.respuestas || {};

const lineas = [
  `Objetivo: ${(r.objetivo || []).join(', ') || '-'}`,
  `Historial de tratamientos: ${r.historial || '-'}`,
  `Busca: ${r.recurrencia || '-'}`,
  `Presupuesto por sesión: ${r.presupuesto || '-'}`,
  `Plazo: ${r.plazo || '-'}`,
  r.detonante ? `Motivo concreto: ${r.detonante}` : null,
  `Municipio: ${r.municipio || '-'}`,
].filter(Boolean).join('\n');

return [{
  json: {
    cliente: body.cliente || '',
    email: body.email || '',
    telefono: body.telefono || '',
    score_parcial: body.score_parcial ?? '',
    timestamp: body.timestamp || '',
    respuestas_texto: lineas,
  },
}];

